/* Komponen dan interaksi website. Isi teks utama ada di content.js. */
(() => {
  'use strict';
  const S = window.SITE;
  const page = document.body.dataset.page || 'beranda';
  const nav = [['beranda','Beranda','index.html'],['tugas','Tugas dan Fungsi','tugas-dan-fungsi.html'],['visi','Visi Misi','visi-misi.html'],['sejarah','Sejarah','sejarah.html'],['kontak','Kontak','kontak.html']];
  const e = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const paths = {
    document:'<path d="M14 2H5a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V9z"/><path d="M14 2v7h7M7 13h10M7 17h7"/>',
    cancel:'<circle cx="12" cy="12" r="9"/><path d="m9 9 6 6m0-6-6 6"/>',
    users:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 4a3 3 0 0 1 0 6m2 4a6 6 0 0 1 3 5v2"/>',
    transfer:'<path d="M4 7h16m-4-4 4 4-4 4M20 17H4m4-4-4 4 4 4"/>',
    search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',
    clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',
    star:'<path d="m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z"/>',
    shield:'<path d="m12 2 8 3v7c0 5-8 10-8 10S4 17 4 12V5z"/><path d="m8 11 3 3 5-5"/>',
    pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0z"/><circle cx="12" cy="10" r="2.5"/>',
    phone:'<path d="M6 3H3c-2 10 8 20 18 18v-4l-5-2-2 2a14 14 0 0 1-7-7l2-2z"/>',
    mail:'<rect x="2" y="4" width="20" height="16" rx="2"/><path d="m2 5 10 8L22 5"/>',
    book:'<path d="M12 5c-3-3-7-3-10-2v16c4-1 7-1 10 2 3-3 6-3 10-2V3c-3-1-7-1-10 2zM12 5v16"/>',
    instagram:'<rect x="3" y="3" width="18" height="18" rx="5"/><circle cx="12" cy="12" r="4"/><circle cx="17.5" cy="6.5" r=".8" fill="currentColor" stroke="none"/>',
    whatsapp:'<path d="M21 11.5a9 9 0 0 1-13 8L3 21l1.5-5A9 9 0 1 1 21 11.5Z"/><path d="m8 7 2 3-1 1c1 2 2 3 4 4l1-1 3 1c-1 4-6 1-8-1S5 8 8 7Z"/>',
    check:'<path d="m5 12 4 4L20 5"/>'
  };
  const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name] || paths.document}</svg>`;
  const brand = () => `<a class="brand" href="index.html"><img src="assets/logo-kemenhaj.png" alt="Logo Kementerian Haji dan Umrah" width="60" height="60"><div><strong>${e(S.name)}</strong><span>${e(S.city)}</span></div></a>`;
  const hours = () => S.hours.map(([day,time])=>`<div class="hour-row"><span>${e(day)}</span><b>${e(time)}</b></div>`).join('');
  const menu = () => nav.map(([id,label,url])=>`<a href="${url}"${page===id?' class="active" aria-current="page"':''}>${label}</a>`).join('');
  const contactLinks = () => `<div class="social-links" aria-label="Kanal kontak resmi">
    <a href="${e(S.contact.instagram)}" target="_blank" rel="noopener" aria-label="Instagram Kemenhaj Salatiga">${icon('instagram')}<span>Instagram</span></a>
    <a href="https://wa.me/${e(S.contact.whatsapp)}" target="_blank" rel="noopener" aria-label="WhatsApp Kemenhaj Salatiga">${icon('whatsapp')}<span>WhatsApp</span></a>
    <a href="mailto:${e(S.contact.email)}" aria-label="Email Kemenhaj Salatiga">${icon('mail')}<span>Email</span></a>
    <a href="${e(S.contact.mapsUrl)}" target="_blank" rel="noopener" aria-label="Lokasi kantor di Google Maps">${icon('pin')}<span>Lokasi</span></a>
  </div>`;
  document.getElementById('site-header').innerHTML = `<header class="header"><div class="wrap header-inner">${brand()}<button class="menu-toggle" aria-expanded="false" aria-controls="main-nav">Menu</button><nav class="nav" id="main-nav" aria-label="Navigasi utama">${menu()}</nav></div></header>`;
  document.getElementById('site-footer').innerHTML = `<footer class="footer"><div class="wrap"><div class="footer-grid"><div>${brand()}<p>Mendampingi langkah jamaah dengan informasi yang jelas dan pelayanan yang lebih mudah dijangkau.</p>${contactLinks()}</div><div><h3>Jelajahi</h3><div class="footer-links">${nav.map(([,label,url])=>`<a href="${url}">${label}</a>`).join('')}</div></div><div><h3>Jam pelayanan</h3><p>Senin–Kamis: 07.30–16.00 WIB<br>Jumat: 07.30–16.30 WIB</p><p>Jadwal dapat menyesuaikan hari libur.</p></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} ${e(S.name)} ${e(S.city)}</span></div></div></footer>`;
  const intro = (title,description) => `<div class="wrap"><div class="breadcrumbs"><a href="index.html">Beranda</a><span>/</span>${e(title)}</div><div class="page-intro"><h1>${e(title)}</h1><p>${e(description)}</p></div>`;
  const note = text => `<aside class="editor-note">${text}</aside>`;
  const faq = () => `<div class="faq">${S.faqs.map(([q,a])=>`<details><summary>${e(q)}</summary><p>${e(a)}</p></details>`).join('')}</div>`;
  const schedule = (contact=false) => `<section class="panel schedule" id="jam-layanan">${icon('clock')}<h2>Jam layanan</h2><p>Kami siap membantu persiapan ibadah Anda.</p><div style="margin-top:18px">${hours()}</div><p class="small-note">Di luar hari libur nasional dan perubahan jadwal kantor.</p>${contact?'':'<a class="btn btn-light" href="kontak.html">Informasi kunjungan</a>'}</section>`;
  function home(){return `<section class="hero"><img class="hero-image" src="assets/hero-haji.png" alt="Ilustrasi suasana ibadah di Masjidil Haram" fetchpriority="high"><div class="wrap"><div class="hero-content"><div class="eyebrow">Melayani dengan sepenuh hati</div><h1>${e(S.hero.title)}</h1><p>${e(S.hero.text)}</p><div class="actions"><button class="btn btn-gold" data-service="pendaftaran">Panduan Pendaftaran</button><a class="btn btn-outline" href="#cek-porsi">Cek Porsi Haji</a></div></div></div></section><div class="wrap"><div class="quick-row"><a href="#layanan">${icon('document')}<div><strong>Panduan layanan</strong><small>Persyaratan & tahapan</small></div></a><a href="#cek-porsi">${icon('search')}<div><strong>Estimasi keberangkatan</strong><small>Akses layanan pusat</small></div></a><a href="kontak.html">${icon('clock')}<div><strong>Jam pelayanan</strong><small>Rencanakan kunjungan</small></div></a></div><section class="section" id="layanan"><div class="section-head"><div><div class="eyebrow">Informasi pelayanan</div><h2>Layanan untuk Jamaah</h2></div><p>Pahami persyaratan dan setiap tahapan pelayanan sebelum mengajukan permohonan.</p></div><div class="cards">${S.services.map(s=>`<article class="service-card"><div class="icon-box">${icon(s.icon)}</div><h3>${e(s.title)}</h3><p>${e(s.summary)}</p><button class="text-button" data-service="${s.id}" aria-label="Lihat panduan ${e(s.title)}">Lihat panduan</button></article>`).join('')}</div></section><div class="utility"><section class="panel" id="cek-porsi">${icon('search')}<h2>Cek estimasi keberangkatan</h2><p>Siapkan 10 digit nomor porsi Anda. Pengecekan dilakukan langsung melalui layanan resmi Kementerian Haji dan Umrah.</p><div class="actions"><a class="btn btn-dark" href="${S.links.estimation}" target="_blank" rel="noopener">Buka Layanan Pusat</a></div><p class="small-note">Membuka situs resmi di tab baru. Estimasi dapat berubah sesuai kuota dan kebijakan.</p></section>${schedule()}</div></div><section class="steps-band section"><div class="wrap"><div class="eyebrow">Mulai dari sini</div><h2>Daftar haji dalam 5 langkah</h2><ol class="steps"><li><b>Siapkan berkas</b><span>Lengkapi dokumen identitas.</span></li><li><b>Setoran awal</b><span>Kunjungi bank penerima setoran.</span></li><li><b>Ajukan pendaftaran</b><span>Verifikasi data dan perekaman foto.</span></li><li><b>Terima nomor porsi</b><span>Periksa dan simpan SPH.</span></li><li><b>Cek estimasi</b><span>Pantau melalui layanan resmi.</span></li></ol></div></section><section class="section"><div class="wrap faq-layout"><div><div class="eyebrow">Temukan jawaban</div><h2>Sering ditanyakan<br>oleh jamaah.</h2><p>Informasi awal untuk membantu Anda mempersiapkan kunjungan.</p><div class="actions"><a class="btn btn-light" href="kontak.html">Informasi kontak</a></div></div>${faq()}</div></section>`}
  function vision(){return intro('Visi & Misi','Arah pelayanan yang berorientasi pada kepentingan jamaah.')+`<div class="page-content"><section class="vision-banner">${icon('star')}<h2>VISI</h2><p>${e(S.vision)}</p></section>${note('Ringkasan arah pelayanan yang diadaptasi dari profil kementerian pusat. Misi di bawah merupakan draf untuk pembahasan, bukan kutipan dokumen visi misi Kota Salatiga yang disahkan. <a href="'+S.links.vision+'" target="_blank" rel="noopener">Lihat rujukan kementerian pusat</a>.')}<h2 class="mission-title">Misi Pelayanan</h2><div class="mission-grid">${S.missions.map(([title,body],i)=>`<article class="mission-card">${icon(['users','book','document','shield'][i])}<h3>${e(title)}</h3><p>${e(body)}</p></article>`).join('')}</div></div></div>`}
  function duties(){const list=[['document','Administrasi layanan haji','Membantu jamaah memahami persyaratan pendaftaran, pembatalan, pelimpahan porsi, dan mutasi.'],['book','Informasi dan pembinaan','Menyajikan panduan serta informasi persiapan ibadah yang mudah diakses dan dipahami.'],['users','Koordinasi pelayanan','Mendukung koordinasi layanan dengan pihak terkait sesuai kewenangan dan kebutuhan jamaah.'],['shield','Pendampingan dan pengaduan','Mengarahkan konsultasi serta pengaduan melalui kanal resmi untuk memperoleh tindak lanjut.']];return intro('Tugas dan Fungsi','Mengenal ruang lingkup pelayanan haji di Kota Salatiga.')+`<div class="page-content"><section class="lead-panel"><div class="eyebrow">Fokus pelayanan</div><h2>Melayani, membina, dan mendampingi jamaah.</h2><p>Portal ini membantu masyarakat memahami alur pelayanan dan menemukan informasi yang diperlukan untuk pengurusan administrasi haji.</p></section>${note('Ringkasan untuk presentasi. Rumusan tugas, fungsi, dan kewenangan resmi perlu disesuaikan dengan dokumen organisasi serta standar pelayanan kantor yang disahkan.')}<div class="mission-grid">${list.map(([ic,t,b])=>`<article class="mission-card">${icon(ic)}<h3>${t}</h3><p>${b}</p></article>`).join('')}</div></div></div>`}
  function history(){return intro('Sejarah','Mengenal perjalanan pelayanan haji di Kota Salatiga.')+`<div class="page-content"><section class="lead-panel"><div class="eyebrow">Dari pelayanan menuju kemudahan</div><h2>Lebih dekat dengan jamaah.</h2><p>Pelayanan haji di Kota Salatiga hadir untuk membantu masyarakat mempersiapkan perjalanan ibadah. Portal digital ini dirancang untuk melengkapi layanan tatap muka dengan informasi yang dapat dipelajari dari rumah.</p></section><div class="history">${note('Naskah sejarah lokal masih menunggu dokumen resmi kantor. Bagian ini menampilkan kerangka narasi untuk presentasi, tanpa mengada-adakan tanggal pendirian atau riwayat pejabat.')}<article><h3>Pelayanan kepada masyarakat</h3><p>Pendampingan administrasi dan informasi menjadi bagian penting dalam persiapan ibadah jamaah.</p></article><article><h3>Penguatan layanan kelembagaan</h3><p>Bagian ini disiapkan untuk memuat tonggak pembentukan kantor, perubahan organisasi, dan dokumen penetapan setelah diverifikasi.</p></article><article><h3>Pengembangan akses digital</h3><p>Rancangan portal menyatukan panduan pendaftaran, pembatalan, pelimpahan porsi, mutasi, dan informasi kunjungan dalam satu akses.</p></article></div></div></div>`}
  function contact(){const c=S.contact;return intro('Kontak','Kami siap membantu kebutuhan informasi dan pelayanan Anda.')+`<div class="page-content"><div class="contact-grid"><section class="panel"><div class="eyebrow">Kantor layanan</div><h2>${e(S.name)}<br>${e(S.city)}</h2><div class="contact-details"><a class="contact-line" href="${e(c.mapsUrl)}" target="_blank" rel="noopener">${icon('pin')}<div><b>Lokasi kantor</b><span>Lihat lokasi kantor di Google Maps</span></div></a><a class="contact-line" href="https://wa.me/${e(c.whatsapp)}" target="_blank" rel="noopener">${icon('whatsapp')}<div><b>WhatsApp</b><span>0851-6818-5205</span></div></a><a class="contact-line" href="mailto:${e(c.email)}">${icon('mail')}<div><b>Email</b><span>${e(c.email)}</span></div></a><a class="contact-line" href="${e(c.instagram)}" target="_blank" rel="noopener">${icon('instagram')}<div><b>Instagram</b><span>@kemenhaj.salatiga</span></div></a></div></section>${schedule(true)}</div><section class="source-area"><h3>Persiapan sebelum berkunjung</h3><p>Pelajari panduan layanan dan siapkan berkas sesuai kebutuhan Anda. Ketentuan rinci dan kelengkapan akhir dikonfirmasi kepada petugas.</p><a href="index.html#layanan" class="btn btn-dark">Lihat panduan layanan</a></section></div></div>`}
  const render = {beranda:home,visi:vision,tugas:duties,sejarah:history,kontak:contact};
  document.getElementById('main').innerHTML=(render[page]||home)();
  const toggle=document.querySelector('.menu-toggle'), menuEl=document.querySelector('.nav');
  toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));menuEl.classList.toggle('open',open)});
  document.addEventListener('keydown',ev=>{if(ev.key==='Escape'){menuEl.classList.remove('open');toggle.setAttribute('aria-expanded','false')}});
  const dialog=document.getElementById('service-dialog');
  function openService(id){
    const s=S.services.find(s=>s.id===id);if(!s)return;
    dialog.innerHTML=`<div class="dialog-header"><h2 id="dialog-title">${e(s.title)}</h2><button class="close-dialog" aria-label="Tutup panduan">×</button></div><div class="dialog-body"><p>${e(s.intro)}</p><div class="eligibility faq"><details><summary>${e(s.eligibility.title)}</summary>${s.eligibility.paragraphs.map(x=>`<p>${e(x)}</p>`).join('')}</details></div><h3>Dokumen / berkas yang perlu dipersiapkan</h3><ul class="document-list">${s.documents.map(d=>`<li>${e(d)}</li>`).join('')}</ul>${(s.documentGroups||[]).map(g=>`<section class="document-group"><h4>${e(g.title)}</h4><ul class="document-list">${g.items.map(x=>`<li>${e(x)}</li>`).join('')}</ul></section>`).join('')}<h3>Alur pelayanan</h3><ol>${s.steps.map(x=>`<li>${e(x)}</li>`).join('')}</ol>${note(e(s.note))}<p class="small-note service-basis">Dasar informasi: ${e(s.basis)}</p></div>`;
    dialog.showModal();document.body.style.overflow='hidden';
    dialog.querySelector('.close-dialog').addEventListener('click',()=>dialog.close());
  }
  document.querySelectorAll('[data-service]').forEach(b=>b.addEventListener('click',()=>openService(b.dataset.service)));
  dialog.addEventListener('close',()=>{document.body.style.overflow=''});
  dialog.addEventListener('click',ev=>{if(ev.target===dialog){const r=dialog.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)dialog.close()}});
})();
